$student = function (
    string $id,
    string $name,
    string $email,
    string $headline,
    string $location,
    int $experienceYears,
    string $education,
    array $skills,
    string $cvText,
    string $createdAt
): array {
    return [
        'id' => $id,
        'name' => $name,
        'email' => $email,
        'headline' => $headline,
        'location' => $location,
        'experience_years' => $experienceYears,
        'education' => $education,
        'skills' => $skills,
        'links' => [],
        'cv_text' => $cvText,
        'file_name' => null,
        'metadata' => [
            'emails' => [$email],
            'phones' => [],
            'detected_skills' => $skills,
        ],
        'created_at' => $createdAt,
    ];
};

$offer = function (
    string $id,
    string $title,
    string $company,
    string $location,
    string $type,
    string $description,
    array $requiredSkills,
    string $createdAt
): array {
    return [
        'id' => $id,
        'title' => $title,
        'company' => $company,
        'location' => $location,
        'type' => $type,
        'description' => $description,
        'required_skills' => $requiredSkills,
        'status' => 'published',
        'created_at' => $createdAt,
    ];
};

$application = function (
    string $id,
    string $offerId,
    string $studentId,
    string $status,
    string $appliedAt
): array {
    return [
        'id' => $id,
        'offer_id' => $offerId,
        'student_id' => $studentId,
        'status' => $status,
        'applied_at' => $appliedAt,
    ];
};

